using System;using System.Collections.Generic;using System.IO;using Ashfall.Core;using Ashfall.Modules.Networking;using Ashfall.Integration.Playable.Consumables;
namespace Ashfall.Integration.Playable.Networking {
 public sealed class R24LanResourcesState {public readonly string Actor;public readonly long Epoch,Revision,Acknowledged;public readonly int Builds,Capacity;readonly Dictionary<string,int> reserves;public Dictionary<string,int> Reserves{get{return new Dictionary<string,int>(reserves,StringComparer.Ordinal);}}internal R24LanResourcesState(string actor,long epoch,long revision,long ack,int builds,int capacity,Dictionary<string,int> reserves){Actor=actor;Epoch=epoch;Revision=revision;Acknowledged=ack;Builds=builds;Capacity=capacity;this.reserves=new Dictionary<string,int>(reserves,StringComparer.Ordinal);}
  internal bool SameInventory(R24LanResourcesState other)
  {
   if(other==null||Builds!=other.Builds||Capacity!=other.Capacity||reserves.Count!=other.reserves.Count)return false;
   foreach(var pair in reserves){int amount;if(!other.reserves.TryGetValue(pair.Key,out amount)||amount!=pair.Value)return false;}
   return true;
  }
 }

 public interface IR24LanSupplyDropWorld {bool TryPlace(string family,Float3 desired,out Float3 accepted);}
 public sealed partial class R24LanLobby {
  const string ResourcesFeature="playable.resources/1",SupplyDropCommand="playable.supply.drop/1";R24LanResourcesState ownResources;long resourcesRevision,dropSerial;IR24LanSupplyDropWorld supplyDropWorld;
  public void BindSupplyDropWorld(IR24LanSupplyDropWorld world){Check();if(State!=R24LanLobbyState.Hosting||world==null||supplyDropWorld!=null)throw new InvalidOperationException("One host supply drop world");supplyDropWorld=world;}
  public bool TryReadOwnResources(out R24LanResourcesState state){Check();state=ownResources;return state!=null;}
  public bool OwnsResources(R24LanResourcesState state){return state!=null&&Object.ReferenceEquals(ownResources,state)&&state.Actor==OwnActor&&state.Epoch==Epoch&&(State==R24LanLobbyState.Hosting||state.Acknowledged>=resourcesPredictionSequence);}
  void PublishResources(string actor,CombatActor value,Peer peer,long ack){var row=new R24LanResourcesState(actor,Epoch,checked(++resourcesRevision),ack,value.Builds,value.Capacity,value.Reserves);if(peer==null){ownResources=row;return;}using(var m=new MemoryStream())using(var w=new BinaryWriter(m,Utf8)){w.Write(ack);w.Write(value.Builds);w.Write((byte)value.Capacity);w.Write((byte)value.Reserves.Count);foreach(var entry in value.Reserves){Write(w,entry.Key,16);w.Write(entry.Value);}peer.Resources=Packet(PacketKind.Snapshot,ResourcesFeature,OwnActor,m.ToArray(),row.Revision);}}
  void ReadResources(Packet packet){try{using(var m=new MemoryStream(packet.Payload,false))using(var r=new BinaryReader(m,Utf8)){long ack=r.ReadInt64();int builds=r.ReadInt32(),capacity=r.ReadByte(),count=r.ReadByte();if(packet.BaseSequence!=-1||packet.Sequence<1||ack<0||ack>gameCommandSequence||builds<0||capacity<3||capacity>6||count>8)return;var reserves=new Dictionary<string,int>(StringComparer.Ordinal);for(int i=0;i<count;i++){string family=Read(r,16);int amount=r.ReadInt32();if(amount<0||!SupplyFamily(family)||family=="backpack"||family=="builds"||reserves.ContainsKey(family))return;reserves.Add(family,amount);}if(m.Position!=m.Length||ownResources!=null&&ownResources.Revision>=packet.Sequence)return;ownResources=new R24LanResourcesState(OwnActor,Epoch,packet.Sequence,ack,builds,capacity,reserves);}}catch(InvalidDataException){}catch(IOException){}catch(ArgumentException){}}
  public bool RequestSupplyDrop(string family,int hand,Float3 desired,out string id){Check();id=null;if(!SupplyFamily(family)||hand<0||hand>1||!desired.IsFinite)return false;long token=checked(++dropSerial);id=OwnActor+"/reserve/"+token.ToString(System.Globalization.CultureInfo.InvariantCulture);if(State==R24LanLobbyState.Hosting)return ApplySupplyDrop(OwnActor,token,family,hand,desired,clock.Now);if(State!=R24LanLobbyState.Connected)return false;using(var m=new MemoryStream())using(var w=new BinaryWriter(m,Utf8)){w.Write(token);Write(w,family,16);w.Write((byte)hand);w.Write(desired.X);w.Write(desired.Y);w.Write(desired.Z);w.Write(EstimatedHostTime);return QueueGameCommand(SupplyDropCommand,m.ToArray());}}
  bool ApplySupplyDrop(string actor,long token,string family,int hand,Float3 desired,double stamp){CombatActor owner;R24LanRawTrackingSample raw;int available;Float3 accepted;if(!InventoryLive||sessions.Get(actor)==null||sessions.Get(actor).Life!=Ashfall.Modules.Sessions.SessionLife.Alive||token<1||!SupplyFamily(family)||hand<0||hand>1||!desired.IsFinite||!Finite(stamp)||stamp>clock.Now+.05||clock.Now-stamp>.75||supplyDropWorld==null||sharedSupplies.Count>=4096||!combat.TryGetValue(actor,out owner)||!Fresh(actor,clock.Now,out raw)||(raw.Pose.Flags&(hand==0?2:4))==0||Distance2(raw.Pose.Root.Position,desired)>9||Distance2(hand==0?raw.Pose.Left.Position:raw.Pose.Right.Position,desired)>4||rawWorldClear==null||!rawWorldClear(raw.Pose.Head.Position,desired))return false;
   string id=actor+"/reserve/"+token.ToString(System.Globalization.CultureInfo.InvariantCulture);if(!Wire.IsText(id,128,false)||sharedSupplies.ContainsKey(id))return false;if(family=="backpack"){if(owner.Capacity<=3||WeaponSlots(owner)+FoodSlots(actor)+GrenadeSlots(actor)>=owner.Capacity)return false;available=1;}else if(family=="builds")available=owner.Builds;else owner.Reserves.TryGetValue(family,out available);int amount=Math.Min(available,R24SupplyState.DefaultAmount(family));if(amount<=0||!supplyDropWorld.TryPlace(family,desired,out accepted)||!accepted.IsFinite||Distance2(raw.Pose.Root.Position,accepted)>9||!rawWorldClear(raw.Pose.Head.Position,accepted))return false;
   var item=new R24LanSupplyState(id,family,amount,accepted,"",checked(++supplySequence));if(family=="backpack")owner.Capacity--;else if(family=="builds")owner.Builds-=amount;else owner.Reserves[family]=available-amount;PublishSupply(item);return true;
  }
  void ReadSupplyDrop(string actor,byte[] bytes){try{using(var m=new MemoryStream(bytes,false))using(var r=new BinaryReader(m,Utf8)){long token=r.ReadInt64();string family=Read(r,16);int hand=r.ReadByte();var at=new Float3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());double stamp=r.ReadDouble();if(m.Position==m.Length)ApplySupplyDrop(actor,token,family,hand,at,stamp);}}catch(InvalidDataException){}catch(IOException){}catch(ArgumentException){}}
 }
}
